const payload = msg.payload;

// Defend against malformed/unexpected MQTT payloads instead of throwing and losing the message.
if (!payload || !Array.isArray(payload.temperatures) || typeof payload.device_id !== 'string') {
    node.warn(`Ignoring malformed MQTT payload: ${JSON.stringify(payload)}`);
    return null;
}

// Firmware sends an NTP-synced epoch-seconds timestamp; fall back to "now" if it's ever missing
const timestamp = Number.isFinite(payload.timestamp)
    ? new Date(payload.timestamp * 1000).toISOString()
    : new Date().toISOString();

const rows = payload.temperatures
    .map((temperature_c, sensor_index) => ({
        sensor_index,
        temperature_c,
        timestamp,
        device_id: payload.device_id
    }))
    // Disconnected probes are published as `null` (or any other non-number) — drop them
    // instead of inserting bogus rows.
    .filter(row => typeof row.temperature_c === 'number' && Number.isFinite(row.temperature_c));

if (rows.length === 0) return null;

msg.payload = rows;
return msg;

if (msg.statusCode >= 400) {
    node.error(`Supabase insert failed (${msg.statusCode}): ${msg.payload}`, msg);
    node.status({ fill: 'red', shape: 'dot', text: `HTTP ${msg.statusCode} @ ${new Date().toLocaleTimeString()}` });
} else {
    node.status({ fill: 'green', shape: 'dot', text: `ok @ ${new Date().toLocaleTimeString()}` });
}
return null;
